func _run_tests() -> void:
	var box := await instantiate_scene("res://ui/dialogue_box.tscn")
	if not check("box_exists", box != null, "La scena res://ui/dialogue_box.tscn deve caricarsi correttamente"):
		return

	var text_label := find_by_name(box, "TextLabel") as RichTextLabel
	if not check("text_label", text_label != null, "DialogueBox deve contenere il nodo TextLabel"):
		return

	var finished := false
	if box.has_signal("line_finished"):
		box.connect("line_finished", func(): finished = true)

	var start_time := Time.get_ticks_msec()
	box.call("show_line", "Elena", "Alt! {wait=0.4} Chi va la?")
	await wait_frames(2)

	check("no_tag_visible", not text_label.text.contains("{wait="), "Il testo mostrato in TextLabel non deve contenere la stringa del tag {wait=...}")
	check("text_cleaned", text_label.text.contains("Alt!") and text_label.text.contains("Chi va la?"), "Il testo mostrato deve contenere la battuta visibile pulita")

	await wait_seconds(0.2)
	check("pausing", not finished, "Durante la battuta con il tag di pausa la digitazione non deve terminare subito")

	var elapsed := 0.0
	while not finished and elapsed < 2.5:
		await wait_frames(3)
		elapsed = float(Time.get_ticks_msec() - start_time) / 1000.0

	check("line_finished", finished, "Al termine della battuta deve essere emesso il segnale line_finished")
	check("pause_applied", elapsed >= 0.45, "La pausa del tag deve essere applicata durante la digitazione (tempo misurato: %.2f s)" % elapsed)
